INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist es wahr, dass solche Software immer kostenlos bleibt?', 2, '[{"text": "Nein", "correct": true, "because": "Oft Zahlung nach Testphase nötig"}, {"text": "Ja", "correct": false, "because": "Kosten nach Trial üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaft hat solche Software typischerweise?', 3, '[{"text": "Testphase", "correct": true, "because": "Erlaubt Nutzung vor Kauf"}, {"text": "Open Source", "correct": false, "because": "Quellcode nicht freigegeben"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Arten von Einschränkungen gibt es bei solcher Software?', 5, '[{"text": "Zeitliche Begrenzung", "correct": true, "because": "Trial endet oft"}, {"text": "Funktionale Limits", "correct": true, "because": "Zugang zu Basisversion"}, {"text": "Nörgelmeldungen", "correct": true, "because": "Fordern Zahlung an"}, {"text": "Farbcodierung", "correct": false, "because": "Kein Einschränkungstyp"}, {"text": "Hohe Speichergröße", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Solche Software ist oft zeitlich begrenzt. b) Sie ist immer Open Source.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, meist proprietär"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Nutzung solcher Software?', 4, '[{"text": "Lizenzbedingungen", "correct": false, "because": "Bestimmen Nutzung"}, {"text": "Testdauer", "correct": false, "because": "Beeinflusst Zugriff"}, {"text": "Verpackungsdesign", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob solche Software immer voll funktionsfähig ist?', 2, '[{"text": "Nein", "correct": true, "because": "Oft eingeschränkte Funktionen"}, {"text": "Ja", "correct": false, "because": "Häufig limitiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme schützt vor Risiken bei solcher Software?', 4, '[{"text": "Download von vertrauenswürdigen Quellen", "correct": true, "because": "Minimiert Malware"}, {"text": "Schnelles Installieren", "correct": false, "because": "Kein Schutz"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass solche Software immer sicher ist. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Kann Malware enthalten"}, {"text": "Ja", "correct": false, "because": "Risiken durch Adware"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist solche Software dasselbe wie Freeware?', 2, '[{"text": "Nein", "correct": true, "because": "Freeware dauerhaft kostenlos"}, {"text": "Ja", "correct": false, "because": "Shareware oft kostenpflichtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Software gehört typischerweise zu dieser Kategorie?', 5, '[{"text": "WinRAR", "correct": true, "because": "Trial mit Nörgelmeldungen"}, {"text": "Adobe Photoshop", "correct": true, "because": "Zeitlich begrenzte Testversion"}, {"text": "Linux Kernel", "correct": false, "because": "Open Source"}, {"text": "Microsoft Office", "correct": false, "because": "Kommerziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Nutzung solcher Software?', 4, '[{"text": "Prüfung der Quelle", "correct": true, "because": "Sichert Vertrauen"}, {"text": "Schnelle Installation", "correct": false, "because": "Sicherheit wichtiger"}, {"text": "Visuelles Design", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Solche Software kann Adware enthalten. b) Sie ist immer lizenzfrei.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, meist lizenziert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um solche Software sicher zu nutzen?', 3, '[{"text": "Antivirenprogramm", "correct": false, "because": "Schützt vor Malware"}, {"text": "Lizenzprüfung", "correct": false, "because": "Sichert Legalität"}, {"text": "Farbanpassung", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, wie ich solche Software sicher herunterlade?', 4, '[{"text": "Von offiziellen Webseiten", "correct": true, "because": "Minimiert Risiken"}, {"text": "Von beliebigen Portalen", "correct": false, "because": "Erhöht Malware-Risiko"}, {"text": "Ohne Prüfung", "correct": false, "because": "Gefährlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass solche Software immer zeitlich begrenzt ist. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Kann auch funktional eingeschränkt sein"}, {"text": "Ja", "correct": false, "because": "Nicht immer zeitlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip beschreibt solche Software am besten?', 4, '[{"text": "Try before you buy", "correct": true, "because": "Test vor Kauf"}, {"text": "Immer kostenlos", "correct": false, "because": "Oft kostenpflichtig"}, {"text": "Open Source", "correct": false, "because": "Quellcode nicht offen"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Donationware dasselbe wie solche Software?', 2, '[{"text": "Nein", "correct": true, "because": "Donationware freiwillige Zahlung"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Modelle"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken gibt es bei solcher Software?', 5, '[{"text": "Malware", "correct": true, "because": "Kann Schadcode enthalten"}, {"text": "Datenlecks", "correct": true, "because": "Adware kann Daten senden"}, {"text": "Hohe Speicherkosten", "correct": false, "because": "Kein typisches Risiko"}, {"text": "Bunte Oberfläche", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Nutzung solcher Software unwichtig?', 3, '[{"text": "Sicherheitsprüfung", "correct": false, "because": "Schützt vor Risiken"}, {"text": "Lizenzbedingungen", "correct": false, "because": "Regeln Nutzung"}, {"text": "Dateiname", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
